const docs = {
  1: "running shoes trail running",
  2: "blue running gear",
  3: "running running running shoes shoes",
};
const stop = new Set(["the", "a", "and", "of"]);
const analyze = (t) => t.toLowerCase().split(/\s+/).filter((w) => w && !stop.has(w));

const postings = {};
const tf = {};
for (const id of Object.keys(docs).map(Number).sort((a, b) => a - b)) {
  tf[id] = {};
  for (const term of analyze(docs[id])) {
    (postings[term] ||= new Set()).add(id);
    tf[id][term] = (tf[id][term] || 0) + 1;
  }
}

const query = analyze("running shoes");
const cand = new Set();
for (const term of query) for (const id of postings[term] || []) cand.add(id);

const scored = [...cand].map((id) => {
  let s = 0;
  for (const term of query) s += tf[id][term] || 0;
  return { id, s };
});
scored.sort((a, b) => (b.s - a.s) || (a.id - b.id));
console.log(scored.map((x) => x.id).join(","));

