const docs = { 1: "Running Shoes", 2: "Blue Dress", 3: "Trail Running" };
const analyze = (t) => t.toLowerCase().split(/\s+/).filter(Boolean);
const postings = {};
for (const id of [1, 2, 3]) for (const w of analyze(docs[id])) (postings[w] ||= []).push(id);

function search(q) {
  // BUG: the raw query is looked up directly, so 'Running' never matches the indexed token 'running'.
  // FIX: analyze the query with the SAME analyzer used at index time before looking it up.
  const terms = analyze(q);
  const hits = new Set();
  for (const t of terms) for (const id of postings[t] || []) hits.add(id);
  return [...hits].sort((a, b) => a - b);
}
console.log(search("Running").join(","));
